set-variable.value:
@{
            string s = (string)context.Variables["speech-cd"];
            int i = s.IndexOf("|");
            long t = 0;
            if (i > 0) { long.TryParse(s.Substring(0, i), out t); }
            return t;
        }

@{
            string s = (string)context.Variables["speech-cd"];
            int i = s.IndexOf("|");
            long t = 0;
            if (i >= 0) { long.TryParse(s.Substring(i + 1), out t); }
            return t;
        }

@{
            bool ok0 = (bool)context.Variables["speech-ok-0"];
            bool ok1 = (bool)context.Variables["speech-ok-1"];
            if (ok0 == ok1) { return ok0 ? (new Random().Next(2) == 0 ? "0" : "1") : "none"; }
            return ok0 ? "0" : "1";
        }

set-header.value:
@{
                            long soonest = Math.Min((long)context.Variables["speech-cd-0"], (long)context.Variables["speech-cd-1"]);
                            double secs = (soonest - DateTime.UtcNow.Ticks) / (double)TimeSpan.TicksPerSecond;
                            return Math.Max(1, (int)Math.Ceiling(secs)).ToString();
                        }

set-variable.value:
@{
                    int s;
                    if (!int.TryParse(context.Response.Headers.GetValueOrDefault("Retry-After", ""), out s)) { s = 30; }
                    return Math.Min(Math.Max(s, 5), 60);
                }

cache-store-value.value:
@{
                    string s = (string)context.Variables["speech-cd-latest"];
                    int i = s.IndexOf("|");
                    string p0 = i > 0 ? s.Substring(0, i) : "0";
                    string p1 = i >= 0 ? s.Substring(i + 1) : "0";
                    string until = DateTime.UtcNow.AddSeconds((int)context.Variables["speech-cd-secs"]).Ticks.ToString();
                    return (string)context.Variables["speech-target"] == "0" ? until + "|" + p1 : p0 + "|" + until;
                }

set-header.value:
@{
                        bool isZero = (string)context.Variables["speech-target"] == "0";
                        bool otherOk = isZero ? (bool)context.Variables["speech-ok-1"] : (bool)context.Variables["speech-ok-0"];
                        if (otherOk) { return "1"; }
                        long otherUntil = isZero ? (long)context.Variables["speech-cd-1"] : (long)context.Variables["speech-cd-0"];
                        int otherSecs = (int)Math.Ceiling((otherUntil - DateTime.UtcNow.Ticks) / (double)TimeSpan.TicksPerSecond);
                        return Math.Max(1, Math.Min((int)context.Variables["speech-cd-secs"], otherSecs)).ToString();
                    }
